import sys

def main():
    d = sys.stdin.read().split()
    n, m, k = int(d[0]), int(d[1]), int(d[2])
    col = d[3:3 + n]
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    p = 3 + n
    for _ in range(m):
        a = find(int(d[p]) - 1)
        b = find(int(d[p + 1]) - 1)
        p += 2
        if a != b:
            parent[a] = b
    size = {}
    freq = {}
    for i in range(n):
        r = find(i)
        size[r] = size.get(r, 0) + 1
        key = (r, col[i])
        freq[key] = freq.get(key, 0) + 1
    best = {}
    for (r, _), f in freq.items():
        if f > best.get(r, 0):
            best[r] = f
    print(sum(size[r] - best[r] for r in size))

main()

